SELECT icd_code, long_title
FROM d_icd_diagnoses
WHERE icd_code = 'icd9|v4986';

SELECT MIN(charttime) AS first_procedure_time
FROM procedures_icd
WHERE subject_id = 10018081 AND charttime >= '2099-12-31 23:59:00' AND charttime <= '2100-12-31 23:59:00';

SELECT DISTINCT subject_id, drug, starttime FROM prescriptions
WHERE drug LIKE '%dextromethorphan-guaifenesin%'
AND date(starttime) BETWEEN '2100-01-01' AND '2100-12-31';

SELECT COUNT(DISTINCT subject_id) AS num_patients_senna
FROM prescriptions
WHERE LOWER(drug) LIKE '%senna%';
